```python
import uuid
from langsmith import evaluate
from langsmith.schemas import Example

dataset_id = uuid.uuid4()
preguntas = [
    "Do you carry staplers?",
    "What is your return policy?",
    "I'm looking for pet food for my cats, do you carry Purina?",
]
examples = [Example(id=uuid.uuid4(), dataset_id=dataset_id, inputs={"question": q}) for q in preguntas]

def app_v2(inputs: dict) -> dict:
    if "pet food" in inputs["question"]:
        return {"response": "Sorry, we only sell office supplies."}
    return {"response": "OfficeFlow can help with that!"}

def mentions_officeflow(outputs: dict) -> bool:
    return "officeflow" in outputs["response"].lower()

def short_answer(outputs: dict) -> dict:
    n = len(outputs["response"].split())
    return {"key": "short_answer", "score": n <= 6, "comment": f"{n} palabras"}

results = evaluate(app_v2, data=examples, evaluators=[mentions_officeflow, short_answer], upload_results=False)

for row in results:
    pregunta = row["example"].inputs["question"]
    scores = {r.key: r.score for r in row["evaluation_results"]["results"]}
    print(f"{pregunta[:30]:30} -> {scores}")
```

